    h,w=len(inp),len(inp[0])
    seen=[[False]*w for _ in range(h)]; out=[]
    for r in range(h):
        for c in range(w):
            if inp[r][c]!=0 and not seen[r][c]:
                col=inp[r][c]; stack=[(r,c)]; seen[r][c]=True; cells=[]
                while stack:
                    rr,cc=stack.pop(); cells.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<h and 0<=nc<w and not seen[nr][nc] and inp[nr][nc]==col:
                            seen[nr][nc]=True; stack.append((nr,nc))
                out.append((col,cells))
    return out
def f2(inp):
    h,w=len(inp),len(inp[0]); out=[[0]*w for _ in range(h)]
    # draw small (size<=2) components first, then large ones
    for col,cells in sorted(comps(inp), key=lambda x:(-x[1]),reverse=False)[:0]: pass
    for col,cells in sorted(comps(inp), key=lambda x:(len(x[1]),-x[0])):
        rs=[p[0] for p in cells]; cls=[p[1] for p in cells]
        for rr in range(min(rs),max(rs)+1):
            for cc in range(min(cls),max(cls)+1):
                out[rr][cc]=col
    return out
