def variant(inp, mode):
    # mode: 'enc_rect'|'enc_max'|'del_stray'|'stray1'
    O=comps(inp); h,w=len(inp),len(inp[0])
    rects=[o for o in O if len(o[5])===(o[4]-o[2]+1)*(o[5]-o[3]+1)]
    nonrect=[o for o in O if o not in rects]
    def cover(o,r,c): return o[1]<=r<=o[4] and o[2]<=c<=o[5]
    res=[[inp[r][c] for c in range(w)] for r in range(h)]
    for o in nonrect:
        for (r,c) in list(o[5]): continue
        for r in range(o[2],o[4]+1):
            for c in range(o[3],o[5]+1):
                if (r,c) in o[5]: continue
                # candidates: rect comps covering
                cand=[rt for rt in rects if cover(rt,r,c)]
                if mode=='enc_rect' and cand:
                    res[r][c]=cand[0][0]
                elif mode=='enc_max':
                    best=max(cand,key=lambda rt:(rt[4]-rt[2]+1)*(rt[5]-rt[3]+1)) if cand else None
                    res[r][c]=best[0] if best else 1
                elif mode=='del_stray':
                    res[r][c]=0
                else: # stray1: hole in nonrect -> 1; inside rect -> rect color
                    res[r][c]=cand[0][0] if cand else 1
    return res
