def comps6(inp):
    h,w=len(inp),len(inp[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for r in range(h):
        for c in range(w):
            if inp[r][c]!=0 and not seen[r][c]:
                col=inp[r][c]; st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    rr,cc=st.pop(); cells.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<h and 0<=nc<w and not seen[nr][nc] and inp[nr][nc]==col:
                            seen[nr][nc]=True; st.append((nr,nc))
                out.append((col,cells))
    return out

def solve(inp):
    H,W=len(inp),len(inp[0])
    C=comps6(inp)
    res=[r[:] for r in inp]
    for col,cells in C:
        if len(cells)!=1: continue
        r,c=cells[0]
        nbs=[inp[r+dr][c+dc] for dr in (-1,0,1) for dc in (-1,0,1)
             if (dr or dc) and 0<=r+dr<H and 0<=c+dc<W]
        cc=Counter(nbs); mx=max(cc.values())
        cand=[k for k,v in cc.items() if v==mx]
        if len(cand)==1: res[r][c]=cand[0]
    return res

